WITH topics AS (SELECT l.project_id, l.topic, l.agent_id, max(l.id) AS watermark, count(*) AS lesson_count FROM memory.lessons l JOIN memory.lesson_stages ls ON ls.id = l.stage_id AND ls.code IN ('daily', 'long_term') WHERE l.archived_at IS NULL AND l.topic IS NOT NULL AND l.topic NOT LIKE 'shared:%' AND l.topic NOT LIKE 'verifier:%' AND l.project_id IS NOT NULL GROUP BY l.project_id, l.topic, l.agent_id HAVING count(*) >= 2), named AS (SELECT t.project_id, p.project_path, t.topic, t.agent_id, a.name AS agent_name, t.watermark, t.lesson_count, CASE WHEN a.name IS NULL THEN t.topic ELSE t.topic || '-' || a.name END AS folder FROM topics t JOIN projects.projects p ON p.id = t.project_id LEFT JOIN agents.agents a ON a.id = t.agent_id WHERE p.project_path <> '(no project)') SELECT n.project_id, n.project_path, n.topic, n.agent_id, n.agent_name, n.folder, n.watermark FROM named n WHERE NOT EXISTS (SELECT 1 FROM memory.skill_drafts d WHERE d.project_id = n.project_id AND d.folder = n.folder AND d.lesson_watermark >= n.watermark) AND NOT EXISTS (SELECT 1 FROM memory.skill_draft_failures f WHERE f.project_id = n.project_id AND f.folder = n.folder AND f.lesson_watermark >= n.watermark AND (f.attempts >= 3 OR f.last_failed_at > now() - interval '1 hour' * (2 ^ f.attempts))) ORDER BY n.lesson_count DESC, n.watermark DESC LIMIT 1
